-- StudyShare demo data: longer descriptions (two sentences) for the existing seed materials.
-- Data only (not a schema change), so it is not a migration. The texts match scripts/seed-data.mjs.
--
--   npx supabase db query --remote -f scripts/sql/update-demo-descriptions.sql
--
-- Seed materials are found by their deterministic storage path (<author>/seed-<key>.<ext>), so ids stay the same
-- (shared links, QR codes, comments, ratings and reports keep working). Only rows whose text differs are changed.
-- The updated_at trigger is paused so the materials do not look "edited"; the transaction keeps it all-or-nothing.

begin;

alter table public.materials disable trigger materials_set_updated_at;

with new_text (seed_key, description) as (values
  ('pb-intro', 'Конспект на първата лекция: какво е програма, конзолен вход и изход, променливи и типове данни. Всяка тема е с кратък пример на JavaScript, а в края има въпроси за самопроверка преди първото упражнение.'),
  ('pb-conditions', '15 решени задачи с if-else и switch, с обяснения стъпка по стъпка. Задачите вървят от лесни към по-трудни – от сравнение на две числа до вложени проверки и логически оператори, а към всяка има примерен вход и изход.'),
  ('pb-loops', 'Кратък помощен лист за for, while и do-while с примери и типични грешки. Обяснено е кога кой цикъл е най-удобен, как работят break и continue и как да избегнем безкраен цикъл – подходящ за бърз преговор преди изпит.'),
  ('pf-arrays', 'map, filter, reduce, sort и други полезни методи – с примери. Показано е кои методи връщат нов масив и кои променят оригинала, както и как се комбинират във верига за решаване на типични задачи от упражненията.'),
  ('pf-regex', 'Основен синтаксис, групи, квантори и 10 упражнения с решения. Обяснени са класовете символи, котвите ^ и $ и флаговете g и i, с примери за проверка на имейл, телефонен номер и дата.'),
  ('jsa-closures', 'Как работят closure-ите в JavaScript, с диаграми и примери. Слайдовете проследяват лексикалния scope, разликата между var, let и const и практически приложения като броячи, частни променливи и фабрични функции.'),
  ('jsa-async', 'От callback-и до async/await: обяснения, примери и чести грешки. Разгледани са Promise.all, обработката на грешки с try/catch и fetch заявки към реален API, с диаграма на event loop-а.'),
  ('jsa-dom', 'Упражнения за селектиране, създаване и промяна на DOM елементи и събития. В архива има HTML шаблон и начален JavaScript код за всяка задача – от прост брояч и списък със задачи до филтриране на таблица в реално време.'),
  ('db-sql', 'Основни SQL заявки, филтриране, групиране и съединения на таблици. Материалът минава през SELECT, WHERE, ORDER BY, GROUP BY и HAVING до INNER и LEFT JOIN, с примери върху малка база данни за университет.'),
  ('db-normal', 'Нормални форми 1NF–3NF с практически примери. Една таблица с повтарящи се данни се разделя стъпка по стъпка, като на всеки етап е обяснено какъв проблем решаваме и кога денормализацията е оправдана.'),
  ('web-flex', 'Сравнение на двата layout модела и кога кой да използваме. Слайдовете показват едни и същи оформления – навигация, карти и цяла страница – направени с Flexbox и с Grid, плюс сравнителна таблица на свойствата.'),
  ('web-responsive', 'Чеклист за responsive сайт: media queries, изображения, типография. Удобен за проверка преди предаване на проект – viewport, mobile-first подход, гъвкави мерни единици и тестване на реални устройства.'),
  ('ai-prompts', 'Как да пишем ясни промптове за AI агенти при разработка на софтуер. С примери за добри и лоши промптове, разделяне на задачата на малки стъпки, даване на контекст и проверка на генерирания код преди commit.'),
  ('ai-supabase', 'Auth, база данни, RLS и Storage – основните стъпки за нов проект. Слайдовете водят от създаването на проект и таблици до регистрация на потребители, качване на файлове и връзка с JavaScript клиента supabase-js.'),
  ('ai-rls', 'Примерни Row-Level Security политики за типични сценарии. Включени са SQL примери за публично четене, редакция само от автора, роля администратор и защита на файлове в Storage, с коментар към всяка политика.'),
  ('pb-nested-loops', 'Рисуване на триъгълници, ромбове и шахматни дъски с вложени цикли. 12 задачи с решения, като към всяка е обяснено как номерът на реда и колоната определят кой символ да се отпечата.'),
  ('pf-objects', 'Създаване, обхождане и сортиране на обекти и асоциативни масиви. Обяснено е кога да ползваме Map вместо обикновен обект, с примери за броене на думи, групиране по ключ и сортиране по стойност.'),
  ('pf-text', 'Най-често използваните методи за низове, с примери от реални задачи. Покрити са split, slice, substring, indexOf, replace и trim, както и как да обработим входа ред по ред и да сглобим резултата.'),
  ('pf-mid-exam', 'Три задачи от междинен изпит с обяснение на подхода и типичните капани. За всяка задача има разбор на условието, решение с коментари и тестове с граничните случаи, на които най-често се губят точки.'),
  ('jsa-classes', 'ООП в JavaScript: класове, наследяване, getters/setters и private полета. Примерите изграждат малка йерархия от класове стъпка по стъпка и показват кога наследяването помага и кога композицията е по-добър избор.'),
  ('jsa-events', 'addEventListener, event bubbling и защо delegation спестява код при динамични списъци. Слайдовете показват фазите на събитието, preventDefault и stopPropagation и как един слушател обслужва цял списък.'),
  ('db-joins', 'INNER, LEFT, RIGHT и FULL JOIN, обяснени с диаграми и малки таблици. До всяка диаграма е резултатът от заявката, така че ясно се вижда кои редове влизат в него и откъде идват NULL стойностите.'),
  ('db-indexes', 'Как индексите ускоряват заявките, кога вредят и как да прочетем EXPLAIN. Сравнени са едни и същи заявки със и без индекс, разгледани са съставните индекси и цената им при INSERT и UPDATE.'),
  ('db-exercises', '20 задачи върху примерна база данни за библиотека: SELECT, GROUP BY, подзаявки. Таблицата съдържа условието, очаквания брой редове и сложността на всяка задача, така че лесно да проверите собственото си решение.'),
  ('web-forms', 'Типове input полета, атрибути за валидация и достъпни етикети. Показано е как работят required, pattern и minlength, как да покажем ясно съобщение за грешка до полето и как да допълним проверката с JavaScript.'),
  ('web-bootstrap', 'Grid, utilities, компоненти и най-полезните класове на една страница. Удобен за разпечатване и бърза справка по време на работа: breakpoints, отстояния, цветове, бутони, карти и форми.'),
  ('web-a11y', 'Семантичен HTML, контраст, фокус и навигация с клавиатура. Включен е кратък чеклист за проверка на собствения сайт и обяснение кога са нужни alt текстове и ARIA атрибути.'),
  ('ai-git', 'commit, branch, merge, rebase и как да оправим грешен commit. Командите са групирани по ситуации – нов проект, работа в клон, конфликт при merge, връщане на промени – кратко и практично, с по едно изречение обяснение.'),
  ('ai-vite-netlify', 'От npm create vite до работещ сайт в Netlify, с environment variables и пренасочвания. В архива има примерен проект с netlify.toml и _redirects, както и стъпките за връзка с GitHub и автоматичен деплой.')
)
update public.materials m
set description = n.description
from new_text n
where m.file_path like '%/seed-' || n.seed_key || '.%'
  and m.description is distinct from n.description;

alter table public.materials enable trigger materials_set_updated_at;

select count(*) filter (where file_path like '%/seed-%') as seed_materials,
       min(char_length(description)) filter (where file_path like '%/seed-%') as shortest,
       max(char_length(description)) filter (where file_path like '%/seed-%') as longest
from public.materials;

commit;
